8.1.3 ایکسس اسپیسیفائرز

ایکسس اسپیسیفائرز وہ تعین کنندہ ہیں جو طے کرتے ہیں کہ کلاس کا کون سا ممبر کلاس/پروگرام کے کس حصے میں قابلِ رسائی ہے۔ C++ میں سب سے عام ایکسس اسپیسیفائرز یہ ہیں:

private ایکسس اسپیسیفائر

public ایکسس اسپیسیفائر

a. private ایکسس اسپیسیفائر

private ایکسس اسپیسیفائر کمپائلر کو بتاتا ہے کہ کلاس میں اس اسپیسیفائر کے بعد بیان کیے گئے اراکین صرف کلاس اور اس کے friend فنکشن کے اندر قابلِ رسائی ہیں۔ private اراکین کلاس کے باہر قابلِ رسائی نہیں ہوتے۔

کلاس کے اندر اور باہر private ڈیٹا ممبرز کا استعمال واضح کرنے والا پروگرام ذیل میں دیا گیا ہے۔

#include<iostream.h>
#include<conio.h>
class Date
{
private:
int Day;
int Month;
int Year;
public:
void SetDate(int nDay, int nMonth, int nYear)
{
Day = nDay;        ┐
Month=nMonth;      ├ Okay: because private members are accessible within the class
Year = nYear;      ┘
cout<< “Today’s date is: "<<Day<< “/"<<Month<< “/"<<Year;
}
};
int main()
{
Date cDate;
//cDate.Day = 10;      ┐
//cDate.Month = 01;    ├ Invalid: because private members cannot be accessible from outside the class
//cDate.Year = 2012;   ┘
cDate.SetDate(15, 01, 2012); //Valid
getch();
return 0;
}

